export const topics: Topic[] = input.map((t) => ({
  ...t,
  dirs: t.sidebar.flatMap((s) => (s.kind === 'links' ? [] : [s.directory])),
}))

/** Strips the locale prefix and returns the first path segment of an entry id or URL path. */
export function firstSegment(id: string): string {
  return stripLocale(id.replace(/^\/+|\/+$/g, '')).split('/')[0] ?? ''
}

/** The topic a page belongs to. `id` = entry id or path, with or without a locale prefix. */
export function topicFor(id: string): Topic | undefined {
  const seg = firstSegment(id)
  return topics.find((t) => t.dirs.includes(seg))
}

/** The sidebar group label of a page, when its directory is a group (flat topics have none). */
export function groupFor(id: string): Localized | undefined {
  const seg = firstSegment(id)
  for (const t of topics) {
    for (const s of t.sidebar) {
      if ((s.kind === 'group' || s.kind === 'api') && s.directory === seg) return s.label
    }
  }
  return undefined
}

export function localize(label: Localized, lang: string): string {
  return isLang(lang) ? label[lang] : label.en
}

export { localizedPath, type Lang } from './locales.ts'
